fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let mut res = Vec::new();
    
    if numbers.is_empty() {
        return res; // Return an empty vector if the input is empty
    }
    
    for (i, &num) in numbers.iter().enumerate() {
        res.push(num); // Add the current number
        if i < numbers.len() - 1 {
            res.push(delim); // Add the delimiter if it's not the last element
        }
    }
    
    res // Return the resulting vector
}